# Build likely output: paint mapped paired-L bounding boxes in reverse map-table order,
# preserving only the current pair's own source cells.
out=[row[:] for row in grid]
pairs={
  2: [[(6,15),(6,16),(7,16)],[(9,13),(10,13),(10,14)]],
  3: [[(5,8),(5,9),(6,8)],[(7,10),(8,9),(8,10)]],
  6: [[(4,6),(4,7),(5,6)],[(6,13),(7,12),(7,13)]],
  7: [[(1,6),(1,7),(2,6)],[(10,8),(11,7),(11,8)]],
}
mapping={3:4,6:8,7:1,8:2,2:4}
# painting order is reverse table order among paired sources: 2, 7, 6, 3
for src in [2,7,6,3]:
    pts=sum(pairs[src],[])
    rs=[r for r,c in pts]; cs=[c for r,c in pts]
    keep=set(pts)
    dst=mapping[src]
    for r in range(min(rs),max(rs)+1):
      for c in range(min(cs),max(cs)+1):
        out[r][c]=src if (r,c) in keep else dst
for row in out: print(' '.join(map(str,row)))
